    def strStr(self, haystack, needle):
        # Empty needle should return 0
        if needle == "":
            return 0
        l = len(needle)
        # If haystack is shorter than the needle, it can't contain it
        if len(haystack) < l:
            return -1
        # Slide a window of length l across haystack
        for i in range(0, len(haystack) - l + 1):
            if haystack[i:i+l] == needle:
                return i
        return -1

